 <body>
   <div id="root"></div>

   <script type="text/babel">
     const { useState, useRef, useEffect } = React;

     function ContactForm() {
       const [formData, setFormData] = useState({
         name: '',
         email: '',
         phone: ''
       });

       const [errors, setErrors] = useState({
         name: '',
         email: '',
         phone: ''
       });

       const [submitStatus, setSubmitStatus] = useState('');

       const nameRef = useRef(null);
       const emailRef = useRef(null);
       const phoneRef = useRef(null);
       const refs = {
         name: nameRef,
         email: emailRef,
         phone: phoneRef
       };

       const validateField = (name, value) => {
         let error = '';
         if (name === 'name') {
           if (!value.trim()) {
             error = 'Error: Full name is required.';
           }
         } else if (name === 'email') {
           if (!value.trim()) {
             error = 'Error: Email address is required.';
           } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
             error = 'Error: Enter a valid email like name@example.com.';
           }
         } else if (name === 'phone') {
           if (value.trim() && !/^[\d\s\-\+\(\)]+$/.test(value)) {
             error = 'Error: Phone number must contain only numbers, spaces, and standard symbols like +, -, ().';
           }
         }
         return error;
       };

       const handleChange = (e) => {
         const { name, value } = e.target;
         setFormData(prev => ({ ...prev, [name]: value }));

         // Clear error as user types, or validate immediately if they already have an error
         if (errors[name]) {
           const error = validateField(name, value);
           setErrors(prev => ({ ...prev, [name]: error }));
         }
       };

       const handleBlur = (e) => {
         const { name, value } = e.target;
         const error = validateField(name, value);
         setErrors(prev => ({ ...prev, [name]: error }));
       };

       const handleSubmit = (e) => {
         e.preventDefault();

         const newErrors = {
           name: validateField('name', formData.name),
           email: validateField('email', formData.email),
           phone: validateField('phone', formData.phone)
         };

         setErrors(newErrors);
         setSubmitStatus('');

         // Find first invalid field and focus it
         const firstInvalidField = ['name', 'email', 'phone'].find(field => newErrors[field]);

         if (firstInvalidField) {
           refs[firstInvalidField].current.focus();
         } else {
           // Success
           setSubmitStatus('Your message has been sent successfully.');
           // Reset form (optional)
           setFormData({ name: '', email: '', phone: '' });
         }
       };

       return (
         <main className="form-container">
           <h1>Contact Support</h1>
           <p className="subtitle">We generally reply within 24 hours.</p>

           {submitStatus && (
             <div className="status-message status-success" role="status" aria-live="polite">
               {submitStatus}
             </div>
           )}

           <p className="help-text" style={{marginBottom: '1rem'}}>
             <span className="required-marker" aria-hidden="true">*</span> indicates a required field
           </p>

           <form onSubmit={handleSubmit} noValidate>
             <div className="form-field">
               <label htmlFor="name">
                 Full name <span className="required-marker" aria-hidden="true">*</span>
               </label>
               <input 
                 ref={nameRef}
                 type="text" 
                 id="name" 
                 name="name" 
                 value={formData.name}
                 onChange={handleChange}
                 onBlur={handleBlur}
                 required 
                 aria-required="true"
                 autoComplete="name"
                 aria-invalid={!!errors.name}
                 aria-describedby={errors.name ? "name-error" : undefined}
               />
               {errors.name && <div id="name-error" className="error-text">{errors.name}</div>}
             </div>

             <div className="form-field">
               <label htmlFor="email">
                 Email address <span className="required-marker" aria-hidden="true">*</span>
               </label>
               <input 
                 ref={emailRef}
                 type="email" 
                 id="email" 
                 name="email" 
                 value={formData.email}
                 onChange={handleChange}
                 onBlur={handleBlur}
                 required 
                 aria-required="true"
                 autoComplete="email"
                 aria-invalid={!!errors.email}
                 aria-describedby={errors.email ? "email-error" : undefined}
               />
               {errors.email && <div id="email-error" className="error-text">{errors.email}</div>}
             </div>

             <div className="form-field">
               <label htmlFor="phone">Phone number</label>
               <input 
                 ref={phoneRef}
                 type="tel" 
                 id="phone" 
                 name="phone" 
                 value={formData.phone}
                 onChange={handleChange}
                 onBlur={handleBlur}
                 autoComplete="tel"
                 aria-invalid={!!errors.phone}
                 aria-describedby={`phone-help ${errors.phone ? 'phone-error' : ''}`.trim()}
               />
               <div id="phone-help" className="help-text">Format: e.g., +1 (555) 123-4567 or 555-123-4567</div>
               {errors.phone && <div id="phone-error" className="error-text">{errors.phone}</div>}
             </div>

             <button type="submit">Send message</button>
           </form>
         </main>
       );
     }

     const root = ReactDOM.createRoot(document.getElementById('root'));
     root.render(<ContactForm />);
   </script>
 </body>
